  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 100);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(200, 400);
  brush.endShape(true);

  // Hills
  brush.fill("#98FB98", 80);
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(200, 300);
  brush.endShape(true);

  // Clouds
  brush.fill("#FAF0E6", 70);
  brush.beginShape();
  brush.vertex(100, 150);
  brush.vertex(150, 100);
  brush.vertex(200, 120);
  brush.vertex(150, 150);
  brush.endShape(true);

  // Sun
  brush.fill("#FF4500", 100);
  brush.beginShape();
  brush.vertex(100, 100);
  brush.vertex(150, 80);
  brush.vertex(200, 100);
  brush.vertex(150, 120);
  brush.endShape(true);
}

